import {createRequire} from 'node:module';
import {readFile,writeFile,mkdir,copyFile,readdir} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {spawnSync} from 'node:child_process';
const modulePath=process.argv[2]??'sharp',batch=Number(process.argv[3]??112),modes=process.argv[4]==='all'?['normal','focus']:['normal'],sharp=createRequire(import.meta.url)(modulePath),root='art/review/web-v3',folder=root+'/recovery-source-calibration-20261025';await mkdir(folder,{recursive:true});
const previous=await readFile(folder+'/coverage.json','utf8').then(JSON.parse).catch(()=>null);if(previous&&previous.batch!==batch){const history=folder+'/history-'+previous.batch;await mkdir(history,{recursive:true});for(const f of await readdir(folder,{withFileTypes:true}))if(f.isFile())await copyFile(folder+'/'+f.name,history+'/'+f.name,1).catch(e=>{if(e.code!=='EEXIST')throw e;});}
const sha=async p=>createHash('sha256').update(await readFile(p)).digest('hex'),reports=[];
for(const profile of ['landscape','portrait'])for(const state of ['reconnecting','session-ended'])for(const mode of modes){
 const tall=profile==='portrait',w=tall?390:1672,h=tall?694:941,prefix=`${batch}-recovery-${state}-${mode}-${profile}-20261025`,record=JSON.parse(await readFile(root+'/'+prefix+'.json','utf8')),capture=folder+`/${state}-${mode}-${profile}-chrome.png`;
 if(record.profile!==profile||record.viewport[0]!==w||Math.abs(record.viewport[1]-h)>1||Math.abs(record.dpr-1)>.001||record.fonts!=='loaded'||!record.images||record.focus.visible!==(mode==='focus')||record.terminal!==(state==='session-ended'))throw Error('Bad capture parity '+prefix);
 const sourceName=mode==='focus'?`${state==='reconnecting'?'29-reconnecting':'30-session-ended'}-focus-${tall&&state==='reconnecting'?'v3':'v2'}.png`:(tall?(state==='reconnecting'?'15-reconnecting-inactive-hand-v3.png':'16-session-ended-v2.png'):(state==='reconnecting'?'15-reconnecting-network-v2.png':'16-session-ended-network-v3.png')),source=`art/mockups/web-v3/${tall?'portrait/':''}${sourceName}`;
 const stitch=spawnSync(process.execPath,['tools/stitch-web-chrome-tiles.mjs',root+'/'+prefix+'.json',capture,modulePath],{encoding:'utf8'});if(stitch.status)throw Error(stitch.stderr);
 const out=folder+`/${state}-${mode}-${profile}`,focus=tall?'68,211,257,269':'440,225,800,470';
 const compare=spawnSync(process.execPath,['tools/compare-web-design.mjs',source,capture,out,modulePath,String(w),String(h),focus],{encoding:'utf8'});if(compare.status)throw Error(compare.stderr);await sharp(out+'-comparison.png').jpeg({quality:95,chromaSubsampling:'4:4:4'}).toFile(out+'-comparison.jpg');
 reports.push({profile,state,mode,source,sourceSha256:await sha(source),capture,captureSha256:await sha(capture),comparison:`${state}-${mode}-${profile}-comparison.jpg`,focus:`${state}-${mode}-${profile}-focus.png`,record,status:'review-required-not-a-pass'});
}
await writeFile(folder+'/coverage.json',JSON.stringify({batch,status:'review-required',scope:'Original fixed recovery-panel pixels and semantic native controls. Normal pointer reading uses native click on blocking scrim; focus uses native Tab. Visual fixture is not real ACK/recovery proof.',reports},null,2)+'\n');
await writeFile(folder+'/index.html',`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>奇术茶馆 · 原稿连接弹层</title><style>body{margin:0;padding:24px;background:#10151d;color:#f4e1b5;font:16px/1.6 system-ui}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,650px),1fr));gap:24px}figure{margin:0}img{display:block;width:100%}a{color:inherit}</style><h1>原稿连接弹层 · 当前${reports.length}组</h1><p>左冻结设计，右${batch}批次Chrome。原稿面板、标题、正文、按钮像素保留，真实控件仍负责焦点、重试和退出。背景头像/HUD/手牌及真实网络边界继续保留，不宣称全页通过。</p><p><a href="coverage.json">来源与捕获</a> · <a href="../../../../docs/63-web-v3-recovery-source-panels.md">本轮报告</a></p><main>${reports.map(r=>`<figure><figcaption>${r.state} · ${r.mode} · ${r.profile}</figcaption><a href="${r.comparison}"><img src="${r.comparison}" alt="左原稿，右Chrome"></a><p><a href="${r.focus}">无损面板局部</a> · <a href="${r.capture.split('/').at(-1)}">Chrome原图</a></p></figure>`).join('')}</main></html>`);console.log({folder,comparisons:reports.length});
